import{_ as t,a as o}from"./chunks/logitech-f710.B7l_xlAJ.js";import{_ as a,o as i,c as s,a5 as n}from"./chunks/framework.BjM_ivYE.js";const g=JSON.parse(`{"title":"Developer's Guide","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/developers-guide.md","filePath":"software/developers-guide.md","lastUpdated":1790672017000}`),r={name:"software/developers-guide.md"};function l(d,e,h,p,c,u){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="developer-s-guide" tabindex="-1">Developer&#39;s Guide <a class="header-anchor" href="#developer-s-guide" aria-label="Permalink to &quot;Developer&#39;s Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><strong>Welcome to the RBQ simulation, command, and deploy/update manual</strong></p><p>This manual provides a comprehensive guide on how to <strong>simulate</strong> the RBQ robot, command it, and <strong>deploy</strong> your own algorithms to the real robot.</p><h2 id="ready-to-use-simulator-and-operator-app-for-developers" tabindex="-1">Ready-to-use simulator and operator app for developers <a class="header-anchor" href="#ready-to-use-simulator-and-operator-app-for-developers" aria-label="Permalink to &quot;Ready-to-use simulator and operator app for developers&quot;">​</a></h2><ul><li><p>The RBQ robot can be simulated accurately using <strong>MuJoCo</strong>: &quot;A fast and accurate physics engine suitable for advanced robotics simulation.&quot;</p><p>📝 <em>Developers can modify the simulation environment &quot;playground&quot; by editing the file:</em> <code>resources/model/rbq_environment.xml</code></p></li><li><p>You command and monitor the robot with the <strong>RBQ</strong> app — the same app you use on real hardware, so anything you rehearse against the simulator carries over unchanged.</p><ul><li>It shows robot status and sensor state, and takes touch, gamepad, or keyboard input.</li><li>Get it from the <strong><a href="/RBQ/manual/downloads/">Downloads</a></strong> page. The whole app is documented under <a href="/RBQ/manual/gui/introduction.html">RBQ App</a>.</li></ul></li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>This repository ships no on-PC control GUI. Earlier versions carried a <code>bin/GUI</code> maintenance tool; it is no longer published, and the <strong>RBQ</strong> app replaces it for every task in this guide.</p></div></div><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ul><li>This section explains how to install and set up the RBQ robot simulation and development environment from scratch.</li></ul><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><p>To run the RBQ simulation and deployment environment smoothly, the following requirements are recommended:</p><ul><li><p>OS: Ubuntu 22.04 (x86)</p><p><img src="'+t+'" alt="Ubuntu 22.04"></p></li><li><p>Minimum PC specs:</p><ul><li>CPU: Intel Core i7 - 12th Gen</li><li>RAM: 16 GB</li><li>Storage: 25 GB</li></ul></li><li><p>Control Devices</p><ul><li>Keyboard: W, A, S, D, Q, E keys, and the arrow keys</li><li>Joystick: Logitech Wireless Gamepad F710 (Recommended)</li></ul><p><img src="'+o+`" alt="Logitech Wireless Gamepad F710"></p></li></ul><h3 id="_1-download-the-rbq-repository" tabindex="-1">1. Download the RBQ Repository <a class="header-anchor" href="#_1-download-the-rbq-repository" aria-label="Permalink to &quot;1. Download the RBQ Repository&quot;">​</a></h3><ul><li>Clone the repository and navigate to the open-source package:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span></code></pre></div><blockquote><p>All scripts, binaries, and SDK code are inside <code>RBQ/</code>. Run all commands from this directory.</p></blockquote><blockquote><p><strong>Note:</strong> Pre-built binaries ship in <code>bin-x86_64/</code> (and <code>bin-aarch64/</code> for arm64). No compilation step is required.</p></blockquote><h2 id="▶-simulation" tabindex="-1">▶ Simulation <a class="header-anchor" href="#▶-simulation" aria-label="Permalink to &quot;▶ Simulation&quot;">​</a></h2><ul><li><p>The simulator runs in Docker — Docker is the only thing to install, and the script offers to install it when it is missing. The first run takes a few minutes to build its image. See <a href="/RBQ/software/simulator/mujoco.html">MuJoCo</a>.</p></li><li><p>Start the <strong>RBQ control modules and the MuJoCo simulator</strong> together from <code>RBQ/</code>:</p></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-gui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span></span></code></pre></div><p><strong>NOTE:</strong> <em><code>ARGUMENTS:</code></em></p><ul><li><p><code>--help</code> : Display help message and exit.</p></li><li><p><code>--vision</code> : Run vision modules (e.g., vision sensors, climb stairs enabled).</p></li><li><p><code>--no-gui</code> : Skip the on-PC GUI. Pass this — the published repository does not carry one.</p></li><li><p>It runs in the foreground of this terminal; Ctrl-C stops it. If Docker needs <code>sudo</code> on this PC, enter your password when asked.</p></li></ul><h3 id="initialize-connect-and-start-the-simulated-robot" tabindex="-1">Initialize - Connect and Start the Simulated Robot <a class="header-anchor" href="#initialize-connect-and-start-the-simulated-robot" aria-label="Permalink to &quot;Initialize - Connect and Start the Simulated Robot&quot;">​</a></h3><p>Start the <strong>RBQ</strong> desktop app <strong>on the same PC</strong> as the simulator. With no robot network around, the app finds the MuJoCo simulator on this PC by itself and connects — see <a href="/RBQ/manual/gui/connection.html">Connection</a>.</p><ol><li>Press <strong>Control</strong> on the hub to open the control home.</li><li>Tap the green <strong>Auto Start</strong> pill, press <strong>Auto Start</strong> in the dialog, and wait for the sequence to report <strong>Done</strong>. Press <strong>Close</strong>.</li><li>Press <code>STAND</code> on the motion card. The robot stands up and is ready for further commands.</li></ol><ul><li>📝 <em>Depending on the posture it starts from, standing up can take a second.</em></li></ul><h3 id="drive-the-robot" tabindex="-1">Drive the Robot <a class="header-anchor" href="#drive-the-robot" aria-label="Permalink to &quot;Drive the Robot&quot;">​</a></h3><p>The motion card carries <code>SIT</code>, <code>STAND</code>, <code>WALK</code>, and <code>STAIRS</code>, and the dashed <strong>Motions</strong> button opens the full grid, where <code>Wave</code> and <code>Run</code> live. What the joysticks do depends on which motion is running — standing, they adjust posture; walking, they drive.</p><p><strong>→ <a href="/RBQ/manual/gui/motion-commands.html">Motion commands</a></strong> has a per-gait axis table, and <strong><a href="/RBQ/manual/gui/control-home.html">Control home</a></strong> covers the rest of the screen, including keyboard driving on a PC.</p><h2 id="real-robot" tabindex="-1">Real Robot <a class="header-anchor" href="#real-robot" aria-label="Permalink to &quot;Real Robot&quot;">​</a></h2><p>This section explains how to operate the <strong>real RBQ robot</strong>.</p><p>📖 <em>For detailed operation steps, refer to the <a href="/RBQ/guides/common/initial-pose.html">Operation Guide</a></em></p><h3 id="_1-connect-to-the-robot" tabindex="-1">1. Connect to the Robot <a class="header-anchor" href="#_1-connect-to-the-robot" aria-label="Permalink to &quot;1. Connect to the Robot&quot;">​</a></h3><ul><li><p>Connect your PC to the robot&#39;s Wi-Fi.</p><p>📝 <em>Wi-Fi SSID: <code>RBQ_xxxx</code>.</em></p></li></ul><h3 id="_2-start-robot-control-in-the-app" tabindex="-1">2. Start Robot Control in the App <a class="header-anchor" href="#_2-start-robot-control-in-the-app" aria-label="Permalink to &quot;2. Start Robot Control in the App&quot;">​</a></h3><p>Open the <strong>RBQ</strong> app and pick the robot in the robot list — see <a href="/RBQ/manual/gui/connection.html">Connection</a>. The status line reads <code>Connected</code> with the route once it is talking to the robot.</p><ul><li>Press <strong>Control</strong> to open the control home.</li><li>Tap <strong>Auto Start</strong>, press <strong>Auto Start</strong> in the dialog, and wait for <strong>Done</strong>. The robot is now activated and ready for operation.</li></ul><h3 id="_3-commands-are-exactly-the-same-as-in-simulation" tabindex="-1">3. Commands are exactly the same as in simulation <a class="header-anchor" href="#_3-commands-are-exactly-the-same-as-in-simulation" aria-label="Permalink to &quot;3. Commands are exactly the same as in simulation&quot;">​</a></h3><ul><li>📝 <em>It is strongly recommended to practice commanding the robot in the simulator first.</em></li></ul><h2 id="update-the-robot" tabindex="-1">Update the Robot <a class="header-anchor" href="#update-the-robot" aria-label="Permalink to &quot;Update the Robot&quot;">​</a></h2><p>Robot software is updated from the app. On the <code>Software update</code> screen, press <strong><code>Send robot software</code></strong> — the robot deploys it as soon as the transfer completes, and the app then offers a reboot.</p><p><strong>→ <a href="/RBQ/manual/gui/software-update.html">Robot Software Update</a></strong></p><p>The app itself is updated from the <code>This app</code> section of the same screen.</p><p><strong>→ <a href="/RBQ/manual/gui/software-update.html">App update</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Put the robot in the <strong>sitting</strong> state before restarting, and do not move it until the restart finishes. Running a mismatched binary and script combination can cause unexpected behavior.</p></div></div><p><code>scripts/deploy.bash</code> is used for local development only — it copies freshly built binaries into <code>~/rbq_ws/</code> on the machine you run it on:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/deploy.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--help</code></td><td>Display help message and exit</td></tr><tr><td><code>--local</code></td><td>Deploy to <code>~/rbq_ws/</code> on the same PC</td></tr><tr><td><code>--pro [FILES...]</code></td><td>Deploy only the named binaries</td></tr></tbody></table>`,48)])])}const f=a(r,[["render",l]]);export{g as __pageData,f as default};
